const payload = $input.first().json.body ?? $input.first().json;
const errors = [];
if (!payload?.submission_id) errors.push('submission_id required');
if (!payload?.email && !payload?.phone) errors.push('email or phone required');
if (!payload?.contact_consent) errors.push('contact_consent required');
const ch = payload?.preferred_channel;
if ((ch === 'whatsapp' || ch === 'both') && !payload?.phone) {
  errors.push('phone required for WhatsApp channel');
}
if ((ch === 'email' || ch === 'both') && !payload?.email) {
  errors.push('email required for email channel');
}
if (errors.length) {
  return [{ json: { valid: false, errors, payload } }];
}
return [{ json: { valid: true, payload } }];

const payload = $('Validate Input').first().json.payload;
const dup = $('Check Duplicate Lead').first().json;
const row = Array.isArray(dup) ? dup[0] : (dup?.reference || dup?.id ? dup : null);
if (row?.reference) {
  return [{ json: { duplicate: true, reference: row.reference, lead_id: row.id, summary: row.ai_summary || 'Already processed', payload } }];
}
return [{ json: { duplicate: false, payload } }];

const payload = $json.payload;
const filter = payload.email
  ? `email=eq.${encodeURIComponent(payload.email)}`
  : `phone=eq.${encodeURIComponent(payload.phone)}`;
return [{ json: { payload, customerFilter: filter } }];

const payload = $('Prepare Customer Lookup').first().json.payload;
const found = $('Find Customer').first().json;
let customerId = null;
if (Array.isArray(found) && found[0]?.id) customerId = found[0].id;
else if (found?.id && !found?.error && !found?.code) customerId = found.id;
return [{ json: { payload, customerExists: Boolean(customerId), customerId } }];

function pickCustomerId(val) {
  if (!val || val.error || val.code) return null;
  if (Array.isArray(val) && val[0]?.id) return val[0].id;
  if (val.id) return val.id;
  return null;
}
function formatHttpError(val) {
  if (!val || typeof val !== 'object') return null;
  if (val.message && (val.code || val.hint || val.details)) {
    return `${val.code || 'error'}: ${val.message}`;
  }
  if (val.error?.message) return val.error.message;
  return null;
}
const ctx = $('Customer Lookup Result').first().json;
const payload = ctx.payload;
let customerId = ctx.customerId || pickCustomerId($input.first()?.json);
if (!customerId && $('Update Customer').isExecuted) {
  customerId = pickCustomerId($('Update Customer').first()?.json);
}
if (!customerId && $('Create Customer').isExecuted) {
  customerId = pickCustomerId($('Create Customer').first()?.json);
}
if (!customerId) {
  customerId = pickCustomerId($('Find Customer').first()?.json);
}
if (!customerId) {
  const parts = [];
  if ($('Create Customer').isExecuted) {
    const err = formatHttpError($('Create Customer').first()?.json);
    if (err) parts.push(`Create Customer: ${err}`);
  }
  if ($('Update Customer').isExecuted) {
    const err = formatHttpError($('Update Customer').first()?.json);
    if (err) parts.push(`Update Customer: ${err}`);
  }
  return [{ json: { customerResolved: false, error: parts.length ? parts.join('; ') : 'Customer upsert failed', payload, customerId: null } }];
}
return [{ json: { customerResolved: true, payload, customerId } }];

const base = $('Resolve Customer Id').first().json;
const rpc = $('Get Lead Reference RPC').first().json;
let reference = null;
if (typeof rpc === 'string') reference = rpc;
else if (Array.isArray(rpc) && rpc[0]) reference = String(rpc[0]);
else if (rpc && typeof rpc === 'object' && !rpc.error) reference = String(Object.values(rpc)[0] || '');
if (!reference || reference === 'undefined') {
  const seq = String(Date.now()).slice(-5);
  reference = `AC-${seq}`;
}
return [{ json: { ...base, reference } }];

const ctx = $('Assign Reference').first().json;
const ref = ctx.reference;
const payload = ctx.payload;
function interestPhrase(payload) {
  const intent = String(payload.intent || payload.category_seed || '').toLowerCase();
  const map = {
    buy: 'buy a vehicle',
    vehicle_purchase: 'buy a vehicle',
    sell: 'sell your vehicle',
    vehicle_sale: 'sell your vehicle',
    trade_in: 'trade in your vehicle',
    test_drive: 'book a test drive',
    financing: 'explore financing',
    find: 'find a vehicle',
    vehicle_search: 'find a vehicle',
    question: 'ask a question',
    general_sales_question: 'ask a question',
  };
  return map[intent] || 'get help from our team';
}
function draftFallbackConfirmation(payload, ref) {
  const name = (payload.name || '').trim().split(/\s+/)[0];
  const hello = name ? `Hi ${name},` : 'Hi,';
  const detail = (payload.message || '').trim();
  const detailBit = detail ? ` Details we captured: "${detail.slice(0, 140)}${detail.length > 140 ? '…' : ''}".` : '';
  return `${hello} thanks for reaching out to ALBA CARS! We have noted your interest to ${interestPhrase(payload)}.${detailBit} Next step: a sales advisor will review your request and follow up shortly. Your reference is ${ref}.`;
}
const fallback = {
  category: payload.category_seed || 'general_sales_question',
  summary: payload.message || 'Website inquiry received.',
  vehicle: {},
  buying_timeline: 'unknown',
  buying_intent: 'medium',
  urgency: 'medium',
  lead_score: 45,
  recommended_action: 'Review inquiry and contact customer.',
  recommended_cta: 'manual_follow_up',
  voice_agent_eligible: false,
  customer_confirmation: draftFallbackConfirmation(payload, ref),
  sales_brief: `Fallback lead ${ref} — AI classification unavailable.`
};
return [{ json: { ...ctx, aiParsed: fallback, aiRaw: { fallback: true, error: $input.first().json } } }];

const ctx = $('Assign Reference').first().json;
const openai = $('OpenAI Classify').first().json;
let parsed;
try {
  const content = openai.choices?.[0]?.message?.content || '{}';
  parsed = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  parsed = { summary: 'Parse error', lead_score: 40, category: 'general_sales_question' };
}
return [{ json: { ...ctx, aiParsed: parsed, aiRaw: openai } }];

const item = $input.first().json;
const payload = item.payload;
const parsed = item.aiParsed || {};
let score = Number(parsed.lead_score);
if (Number.isNaN(score)) score = 0;
score = Math.max(0, Math.min(100, Math.round(score)));
let priority = 'early';
if (score >= 80) priority = 'hot';
else if (score >= 50) priority = 'warm';
const voiceEligible = Boolean(parsed.voice_agent_eligible) && Boolean(payload.phone) && Boolean(payload.voice_consent);
parsed.voice_agent_eligible = voiceEligible;
parsed.lead_score = score;
function interestPhrase(payload) {
  const intent = String(payload.intent || payload.category_seed || '').toLowerCase();
  const map = {
    buy: 'buy a vehicle', vehicle_purchase: 'buy a vehicle',
    sell: 'sell your vehicle', vehicle_sale: 'sell your vehicle',
    trade_in: 'trade in your vehicle', test_drive: 'book a test drive',
    financing: 'explore financing', find: 'find a vehicle', vehicle_search: 'find a vehicle',
    question: 'ask a question', general_sales_question: 'ask a question',
  };
  return map[intent] || 'get help from our team';
}
const name = (payload.name || '').trim().split(/\s+/)[0];
const hello = name ? `Hi ${name},` : 'Hi,';
const defaultConf = `${hello} thanks for reaching out to ALBA CARS! We have noted your interest to ${interestPhrase(payload)}. Next step: a sales advisor will follow up shortly. Your reference is ${item.reference}.`;
const confirmation = parsed.customer_confirmation || defaultConf;
return [{ json: { ...item, parsed, score, priority, voiceEligible, confirmation } }];

const ctx = $('Parse AI and Apply Rules').first().json;
const evaled = $('Evaluate Insert Lead').first().json;
const leadId = evaled.lead_id;
return [{ json: { ...ctx, lead_id: leadId } }];

const openai = $input.first().json;
const hasContent = Boolean(openai?.choices?.[0]?.message?.content);
const hasError = Boolean(openai?.error) || Boolean(openai?.code && !hasContent);
const openaiFailed = hasError || !hasContent;
return [{ json: { ...openai, openaiFailed, openaiError: openai?.error || (openaiFailed ? openai : null) } }];

const ctx = $('Parse AI and Apply Rules').first().json;
const leadRow = $('Insert Lead').first().json;
const lead = Array.isArray(leadRow) ? leadRow[0] : leadRow;
const hasN8nError = Boolean(leadRow?.error);
const hasPgError = Boolean(lead?.code || leadRow?.code);
const leadId = lead?.id && !hasN8nError && !hasPgError ? lead.id : null;
const insertOk = Boolean(leadId);
const error = insertOk
  ? null
  : (leadRow?.error?.message || lead?.message || leadRow?.message || 'Lead insert failed');
return [{ json: { ...ctx, insertOk, lead_id: leadId, error, insertRaw: leadRow } }];
